/** Durations and curves from the token file; whether to animate at all is the component's call, see reduceMotion. */
internal object Motion {
    fun <T> press(): TweenSpec<T> = tween<T>(100, easing = EaseOut)
    fun <T> release(): TweenSpec<T> = tween<T>(350, easing = CubicBezierEasing(.3f, 1.4f, .5f, 1f))
    fun <T> fade(): TweenSpec<T> = tween<T>(250, easing = EaseOut)
    fun <T> spin(): InfiniteRepeatableSpec<T> = infiniteRepeatable(tween<T>(900, easing = LinearEasing))
    fun <T> tick(): TweenSpec<T> = tween<T>(1000, easing = LinearEasing)
    const val staggerMillis = 40
}
